/* Shared screen composition. No additional renderer override layer. */
const isOpenProject=p=>!['Delivered','Archived','Portfolio Queue'].includes(p.status);
const navigationMedia=window.matchMedia?.('(max-width: 700px)');
navigationMedia?.addEventListener('change',()=>{window.studioMotion?.cancel();const side=$('.sidebar');if(side)side.inert=navigationMedia.matches&&!side.classList.contains('open');});
function projectTaskSummary(p){const linked=db.tasks.filter(t=>t.project===p.id);return linked.length?`${linked.filter(t=>t.status==='Done').length}/${linked.length} tasks done`:`No tasks yet <button data-project-task="${esc(p.id)}">Add task</button>`;}
function projects(){
 const open=db.projects.filter(isOpenProject),list=db.projects.filter(p=>(filter==='All'||filter==='Active'&&isOpenProject(p)||p.status===filter)&&(!query||(p.name+' '+p.client).toLowerCase().includes(query.toLowerCase())));
 if(projectSort==='date')list.sort((a,b)=>a.due.localeCompare(b.due));if(projectSort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));
 const card=p=>`<article class="panel project-card" draggable="true" data-drag-project="${esc(p.id)}"><div class="panel-head"><span class="project-drag-handle" draggable="true" title="Drag project to another status" aria-hidden="true">${icon('menu')}</span><h2>${esc(p.name)}</h2>${badge(p.status)}</div><p class="muted">${esc(p.client)}</p><div class="progress-cell"><b>${p.progress}%</b>${progress(p.progress)}</div><div class="project-meta">${projectTaskSummary(p)}</div><div class="row"><div class="row-main"><small>Due ${date(p.due)}</small></div><button data-edit="projects:${esc(p.id)}">Open</button></div><label class="field">Move to<select data-project-status="${esc(p.id)}">${options(projectStatuses,p.status)}</select></label></article>`;
 const table=`<div class="table-wrap"><table><thead><tr><th>Project</th><th>Client</th><th>Status</th><th>Progress</th><th>Due</th><th></th></tr></thead><tbody id="project-rows">${list.map(p=>`<tr><td>${esc(p.name)}<span class="sub">${projectTaskSummary(p)}</span></td><td>${esc(p.client)}</td><td>${badge(p.status)}</td><td><div class="progress-cell">${p.progress}% ${progress(p.progress)}</div></td><td>${date(p.due)}</td><td><button data-edit="projects:${esc(p.id)}">Open</button></td></tr>`).join('')}</tbody></table></div>`;
 return heading('Projects','From first idea to final delivery.',addBtn('projects','New project'))+`<div class="toolbar project-toolbar">${viewButtons('projects',projectView,['Table','Cards','Board'])}${search('Search projects…')}<select id="status-filter" aria-label="Project status">${options(['Active','All','On Hold','Delivered','Portfolio Queue','Archived'],filter)}</select><select id="project-sort" aria-label="Sort projects">${[['recent','Recent'],['date','Due date'],['name','Name']].map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></div><div class="project-insights"><span><b>${money(open.reduce((s,p)=>s+(+p.budget||0),0))}</b> open budget</span><span><b>${open.filter(p=>p.due<today()).length}</b> overdue projects</span><span><b>${open.length?Math.round(open.reduce((s,p)=>s+p.progress,0)/open.length):0}%</b> average completion</span><small>Open includes Planning, In Progress, In Review and On Hold.</small></div>${!list.length?'<div class="empty">No matching projects</div>':projectView==='Table'?table:projectView==='Cards'?`<div class="project-cards">${list.map(card).join('')}</div>`:`<p class="section-note">Drag projects between statuses, or use Move to. Scroll horizontally to explore →</p><div class="project-board" tabindex="0" aria-label="Project status columns">${['Planning','In Progress','In Review','On Hold','Delivered','Portfolio Queue','Archived'].map(s=>`<section class="column" data-project-drop="${s}"><h3>${s} <small>${list.filter(p=>p.status===s).length}</small></h3>${list.filter(p=>p.status===s).map(card).join('')||'<div class="empty">No projects</div>'}</section>`).join('')}</div>`}`;
}
function settings(){
 const tabs=['Studio identity','Appearance','Invoice defaults','Workspace','Data'];
 const form=(id,body,label='Save settings')=>`<form id="${id}"><div class="form-grid">${body}</div><div class="dialog-actions"><button type="submit" class="primary">${label}</button></div></form>`;
 let body='';
 if(settingsTab==='Studio identity')body=panel('Studio identity','layers',form('settings-form',field('Studio name',input('studio',db.settings.studio))+field('Primary brand',input('brand',db.settings.brand))+field('Secondary brand',input('secondary',db.settings.secondary))+field('Owner',input('owner',db.settings.owner))+field('Email',input('email',db.settings.email,'email'))+field('Address',input('address',db.settings.address))+field('Website',input('website',db.settings.website)))+uploadControl('App logo','appLogo',db.settings.appLogo));
 if(settingsTab==='Appearance')body=panel('Appearance','star',form('appearance-form',field('Accent colour',`<input name="accent" type="color" value="${safeAccent(db.settings.accent)}">`)+field('Motion preference',select('motion',['System','Reduced','Off'],db.settings.motion||'System')),'Save appearance')+'<p class="section-note">System follows your device’s reduced motion preference. Reduced uses brief fades. Off disables animation.</p>');
 if(settingsTab==='Invoice defaults')body=panel('Invoice defaults','bills',form('invoice-settings',field('Invoice prefix',input('prefix',db.settings.prefix))+field('Default tax (%)',input('tax',db.settings.tax,'number',true,'min="0" max="100" step=".1"')))+uploadControl('Separate invoice logo','invoiceLogo',db.settings.invoiceLogo)+'<p class="section-note">Uses the app logo when no separate logo is set.</p><button data-go="invoice">Manage invoice templates</button>');
 if(settingsTab==='Workspace')body=panel('Workspace preferences','settings',form('settings-form',field('Display currency',select('currency',['USD','LKR','GBP','EUR','AUD'],db.settings.currency))+field('Revenue target',input('target',db.settings.target,'number',true,'min="1"'))+field('Monthly cycle starts on',`<select name="cycleStartDay">${Array.from({length:31},(_,i)=>`<option value="${i+1}" ${cycleDay()===i+1?'selected':''}>Day ${i+1}</option>`).join('')}</select>`)+field('Monthly cycle ends on',`<select data-cycle-end>${Array.from({length:31},(_,i)=>`<option value="${i+1}" ${(cycleDay()===1?31:cycleDay()-1)===i+1?'selected':''}>${i===30?'Last day of month':'Day '+(i+1)}</option>`).join('')}</select>`)+`<p class="section-note full">Ends the day before the next cycle starts. Short months use their last available day. Current cycle: ${date(cycleRange().start)}–${date(cycleRange().fullEnd)}. Revenue is counted through today.</p>`)+`<p class="section-note">Display currency changes labels, not stored amounts. FX conversion applies only to USD subscriptions.</p>${fxPanel()}<button data-action="export-transactions">Export transactions as CSV</button>`);
 if(settingsTab==='Data')body=panel('Workspace data','download',`<p class="section-note">Signed-out work stays on this device. Connected team work uses the shared cloud workspace. Version 1 backups preserve historical records, including retired feature data.</p><div class="account-actions"><button class="primary" data-action="export">Export backup</button><button data-action="import">Import backup</button></div><hr><h3>Sample workspace</h3><p class="section-note">Export your current records before replacing them.</p><div class="account-actions"><button class="danger" data-action="clear-demo">Clear sample data</button><button data-action="reset-demo">Restore demo</button></div>`);
 return heading('Settings','Make this workspace yours.')+`<div class="tabs settings-tabs">${tabs.map(t=>`<button data-settings-tab="${t}" class="${settingsTab===t?'selected':''}" aria-pressed="${settingsTab===t}">${t}</button>`).join('')}</div><div class="settings-content">${body}</div>`;
}
function bindWorkspaceUI(){
 bindDeliveryControls();
 $$('[data-project-task]').forEach(b=>b.onclick=()=>{edit('tasks');$('#record-form [name="project"]').value=b.dataset.projectTask;});
 $$('[data-range]').forEach(b=>b.onclick=()=>{const previous=captureCharts();financePeriod=b.dataset.range;render();animateCharts(previous);});
 bindChartDetails();
 const menu=$('[data-action="menu"]'),side=$('.sidebar');if(menu)menu.setAttribute('aria-expanded','false');
 if(side)side.inert=window.matchMedia?.('(max-width: 700px)').matches&&!side.classList.contains('open');
 if(menu)menu.onclick=()=>{window.studioMotion?.cancel();const side=$('.sidebar'),open=side.classList.toggle('open');side.inert=!open;menu.setAttribute('aria-expanded',String(open));if(open){window.studioMotion?.run(side,{opacity:[.6,1]},.2,db.settings.motion);side.querySelector('button')?.focus();}};
 if($('.sidebar'))$('.sidebar').onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();window.studioMotion?.cancel();$('.sidebar').classList.remove('open');$('.sidebar').inert=true;menu?.setAttribute('aria-expanded','false');menu?.focus()}if(e.key==='Tab'&&$('.sidebar').classList.contains('open')){const buttons=$$('.sidebar button');if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus()}}};
}
